.card-perma:has(.card__closed),
.card-perma:has(.card--postponed) {
  --card-color: var(--color-card-complete) !important;

  .bubble {
    display: none;
  }
}

.card__closed-title {
  color: var(--stamp-color);
  font-size: 1.3em;
  font-weight: 900;
  position: relative;
  text-align: center;
  text-transform: uppercase;
}

.card__closed-date {
  font-family: var(--font-mono);

